<template><NcSettingsSection :name="t('libresign','Reminders')" :description="t('libresign','Administrator-controlled reminders for ordinary requests and campaign copies. Only the participant whose turn is active is reminded.')"><form class="reminder-policy" @submit.prevent="save"><label class="reminder-switch"><input v-model="policy.enabled" type="checkbox" :disabled="busy">{{ t('libresign','Enable scheduled reminders') }}</label><div class="reminder-grid"><label>{{ t('libresign','Frequency') }}<select v-model.number="policy.intervalHours"><option :value="24">{{ t('libresign','Once daily') }}</option><option :value="12">{{ t('libresign','Twice daily') }}</option><option :value="48">{{ t('libresign','Every two days') }}</option></select></label><label>{{ t('libresign','First reminder after (days)') }}<input v-model.number="policy.firstAfterDays" type="number" min="1" max="365" required></label><label>{{ t('libresign','Send time (WAT)') }}<input v-model="policy.sendTime" type="time" required></label><label v-if="policy.intervalHours===12">{{ t('libresign','Second send time (WAT)') }}<input v-model="policy.secondTime" type="time" required></label><label>{{ t('libresign','Maximum reminders per signer') }}<input v-model.number="policy.maxReminders" type="number" min="1" max="100" required></label><label>{{ t('libresign','Stop after invitation (days)') }}<input v-model.number="policy.stopAfterDays" type="number" min="1" max="365" required></label><label>{{ t('libresign','Remind until (optional)') }}<input v-model="policy.until" type="date"></label></div><p>{{ t('libresign','Reminders stop when the signer signs, the request is cancelled or exempted, the reminder limit is reached, or either stop date is reached. Send times use West Africa Time (UTC+1).') }}</p><p v-if="error" class="reminder-error" role="alert"><strong>{{ error }}</strong></p><p v-if="saved" role="status">{{ t('libresign','Reminder settings saved.') }}</p><NcButton type="submit" variant="primary" :disabled="busy">{{ t('libresign','Save reminder settings') }}</NcButton></form></NcSettingsSection></template>
<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {t} from '@nextcloud/l10n'
import {confirmPassword} from '@nextcloud/password-confirmation'
import NcSettingsSection from '@nextcloud/vue/components/NcSettingsSection'
import NcButton from '@nextcloud/vue/components/NcButton'
import {campaignGet,campaignPost,campaignError} from '../../services/campaigns'
const policy=reactive({enabled:false,intervalHours:24,firstAfterDays:1,maxReminders:10,stopAfterDays:30,sendTime:'09:00',secondTime:'17:00',until:'',timezone:'Africa/Lagos'}),busy=ref(false),error=ref(''),saved=ref(false)
onMounted(async()=>{busy.value=true;try{Object.assign(policy,await campaignGet('admin/reminder-schedule'))}catch(e){error.value=campaignError(e)}finally{busy.value=false}})
async function save(){busy.value=true;error.value='';saved.value=false;try{await confirmPassword();Object.assign(policy,await campaignPost('admin/reminder-schedule',{policy:{...policy}}));saved.value=true}catch(e){error.value=campaignError(e)}finally{busy.value=false}}
</script>
<style scoped>.reminder-policy{max-width:900px}.reminder-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin-block:20px}.reminder-grid label{display:flex;flex-direction:column;gap:6px}.reminder-grid input,.reminder-grid select{width:100%;margin:0;box-sizing:border-box;min-height:44px}.reminder-switch{display:flex;gap:10px;align-items:center}.reminder-policy p{line-height:1.6;margin-bottom:16px}.reminder-error{border-inline-start:5px solid var(--color-error);padding:14px;background:var(--color-background-dark)}</style>
